#include <cstdio>
#include <cwchar>
#include <cstdarg>
#include <cassert>
#include <type_traits>
#include <utility>
int print(std::FILE *file, const wchar_t *format, ...) {
    std::va_list args;
    va_start(args, format);
    int n = std::vfwprintf(file, format, args);
    va_end(args);
    return n;
}
int scan(std::FILE *file, const wchar_t *format, ...) {
    std::va_list args;
    va_start(args, format);
    int n = std::vfwscanf(file, format, args);
    va_end(args);
    return n;
}
int main() {
    std::FILE *file = std::tmpfile();
    assert(file);
    std::fputs("42", file);
    assert(std::fflush(file) == 0);
    std::rewind(file);
    std::fpos_t position;
    assert(std::fgetpos(file, &position) == 0);
    assert(std::fgetc(file) == '4');
    assert(std::fsetpos(file, &position) == 0);
    std::fclose(file);
    std::FILE *wide = std::tmpfile();
    assert(wide);
    std::fwide(wide, 1);
    print(wide, L"%d", 73);
    std::rewind(wide);
    assert(std::fgetwc(wide) == L'7');
    assert(std::ungetwc(L'7', wide) == L'7');
    int number{};
    assert(scan(wide, L"%d", &number) == 1 && number == 73);
    std::rewind(wide);
    number = 0;
    assert(std::fwscanf(wide, L"%d", &number) == 1 && number == 73);
    std::fclose(wide);
    // getchar/getwchar read standard input; ungetc/ungetwc supply a character without
    // interactive input.
    assert(std::ungetc('A', stdin) == 'A');
    assert(std::getchar() == 'A');
}
